CREATE TABLE IF NOT EXISTS dm_index_n.index_grp3_CompScal_OtcDeri_Cs_MthApd( grp_id1 STRING COMMENT '组合ID1', grp_id2 STRING COMMENT '组合ID2', grp_id3 STRING COMMENT '组合ID3',  index_val STRING COMMENT '指标值' , data_time STRING COMMENT '数据时间', modify_operator STRING COMMENT '修改人', modify_time STRING COMMENT '修改时间', status STRING COMMENT '状态 1：可用 0：已失效', index_id STRING COMMENT '指标代码' ) COMMENT '客户*营业部*员工&客户*分公司本部*员工_合约规模_场外衍生品&交叉销售_当月日均_无备注信息' PARTITIONED BY ( busi_mon STRING COMMENT '业务月份', tag_id STRING COMMENT '标签ID' ) STORED AS ORC;